let route='overview',tab='All',query='',category='All categories',accountTab='Overview';
const routes=[['WORKSPACE',[['overview','Overview','overview'],['products','Products','box'],['warehouse','Warehouse','warehouse'],['analytics','Stock health','chart']]],['OPERATIONS',[['sales','Sales orders','receipt'],['purchasing','Purchase orders','bag'],['receiving','Goods received','down'],['containers','Containers','ship']]],['RELATIONSHIPS',[['clients','Clients','users'],['suppliers','Suppliers','supplier']]],['FINANCE',[['invoices','Invoices & payments','wallet'],['accounting','Accounting','bank'],['pricing','Price lists & catalogues','book']]]];
const allRoutes=routes.flatMap(g=>g[1]).concat([['settings','Settings','settings']]);
const $=id=>document.getElementById(id);
const persist=()=>{try{localStorage.setItem('stocky-demo-v1',JSON.stringify(state))}catch{toast('Browser storage is full. Changes remain in this session.')}};
const log=(text,note)=>{state.activity.unshift({text,note,time:'Just now'});state.activity=state.activity.slice(0,12);persist()};
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
const badge=s=>`<span class="badge ${/Paid|Active|Received|Posted|Reconciled|Healthy|Dispatched|Confirmed/.test(s)?'green':/Overdue|Out of stock/.test(s)?'red':/transit/.test(s)?'blue':/Low|Backorder|Unpaid|Unmatched|Ready|Partial/.test(s)?'orange':'neutral'}">${esc(s)}</span>`;
const btn=(label,action,ico='',cls='')=>`<button class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const link=(label,to)=>`<a class="text-link" href="#${to}">${label}${icon('arrow')}</a>`;
const product=id=>state.products.find(p=>p.id===id);
const available=p=>p.stock-p.reserved;
const health=p=>!available(p)?'Out of stock':available(p)<p.reorder?'Low stock':'Healthy';
const prodCell=p=>`<div class="product-cell"><span class="product-art ${p.tone||''}">${icon(p.art||'box')}</span><button class="product-name" data-action="product:${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${esc(p.id)} · ${esc(p.color)}</small></button></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}"><div class="empty"><h3>No results found</h3>Try a different search or add your first record.</div></td></tr>`}</tbody></table></div>`;
const metric=(title,value,foot,ico='box')=>`<div class="metric"><div class="metric-title">${title}${icon(ico)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;
const header=(title,sub,actions='')=>`<div class="page-head"><div><span class="eyebrow">NORTHSTAR / ${route==='overview'?'YOUR BUSINESS AT A GLANCE':route.toUpperCase()}</span><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const tabs=(names,active=tab,action='tab')=>`<div class="tabbar">${names.map(n=>`<button class="tab ${active===n?'active':''}" data-action="${action}:${n}">${n}</button>`).join('')}</div>`;
const toolbar=(placeholder='Search records…',extra='')=>`<div class="toolbar"><label class="search-field">${icon('search')}<input id="table-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}"></label><div class="filters">${extra}${btn('Export CSV','export','down')}</div></div>`;
const bottom=n=>`<div class="table-bottom"><span>${n} ${n===1?'record':'records'} · Sample data</span><span>Page 1 of 1</span></div>`;
const match=(obj)=>Object.values(obj).flat().join(' ').toLowerCase().includes(query.toLowerCase());
function chart(){return `<div class="chart"><svg viewBox="0 0 590 180" preserveAspectRatio="none" role="img" aria-label="Illustrative sales trend, October first week versus previous week"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a7b89e" stop-opacity=".28"/><stop offset="1" stop-color="#a7b89e" stop-opacity="0"/></linearGradient></defs>${[25,65,105,145].map((y,i)=>`<line x1="40" y1="${y}" x2="580" y2="${y}"/><text x="0" y="${y+3}">${[60,40,20,0][i]}k</text>`).join('')}<path d="M40 117C80 116 83 86 130 92S186 120 220 100S275 120 310 85S370 99 400 64S470 87 490 48S550 64 580 35L580 146H40Z" fill="url(#fade)"/><path d="M40 130C85 110 90 138 130 118S190 117 220 131S275 98 310 115S366 106 400 106S460 84 490 97S550 84 580 90" fill="none" stroke="#c6cec0" stroke-width="2" stroke-dasharray="4 5"/><path d="M40 117C80 116 83 86 130 92S186 120 220 100S275 120 310 85S370 99 400 64S470 87 490 48S550 64 580 35" fill="none" stroke="#718769" stroke-width="2.5"/><circle cx="580" cy="35" r="4" fill="#718769" stroke="white" stroke-width="2"/>${['01 Oct','02 Oct','03 Oct','04 Oct','05 Oct','06 Oct','07 Oct'].map((t,i)=>`<text x="${40+i*88}" y="174">${t}</text>`).join('')}</svg></div>`}
function containerMini(c){return `<div class="container-mini"><div class="container-top"><strong>${esc(c.id)}</strong>${badge(c.status)}</div><div class="route-line">${icon('supplier')}<hr>${icon('ship')}<hr>${icon('warehouse')}</div><div class="route-cities"><span>${esc(c.origin)}, China</span><span>${esc(c.destination)}, ZA</span></div><div class="progress"><span style="width:${c.progress}%"></span></div><div class="container-meta"><span>${num(c.cartons)} cartons</span><span>ETA <strong>${esc(c.eta.slice(5))}</strong></span></div></div>`}
function overview(){let low=state.products.filter(p=>health(p)!=='Healthy').length;return header('A little order. A lot of clarity.','Here’s what’s happening across your business today.',btn('7 October 2026','date','calendar')+btn('New transaction','quick','plus','primary'))+`<div class="metric-grid">${metric('Inventory value',money(state.products.reduce((s,p)=>s+p.stock*p.cost,0)),'<b>At landed cost</b> across '+state.products.length+' products','box')}${metric('Sales this month','R 284,650','<b>↗ 12.8%</b> vs. last month · sample','chart')}${metric('Open sales orders',String(state.orders.filter(o=>o.status!=='Dispatched').length).padStart(2,'0'),'<b>'+state.orders.filter(o=>o.status==='Ready to dispatch').length+' ready</b> to pick & dispatch','receipt')}${metric('Stock needs attention',String(low).padStart(2,'0'),'<b class="warn">'+low+' products</b> below reorder level','alert')}</div><div class="dashboard-row"><section class="panel"><div class="panel-head"><div><h2>Sales performance</h2><p>A clearer picture of your trading week.</p></div><span class="badge neutral">This week</span></div><div class="panel-body"><div class="chart-top"><strong>R 86,420</strong><small>↗ 8.2%</small><div class="legend"><span><i></i>This week</span><span><i></i>Last week</span></div></div>${chart()}</div></section><section class="panel"><div class="panel-head"><h2>Needs your attention</h2><span class="badge neutral">${low+2} items</span></div><div class="attention-list"><div class="attention-item"><span class="attention-icon">${icon('box')}</span><div><strong>${low} products running low</strong><p>Keep your bestsellers on the shelf.</p></div><a class="icon-button" aria-label="Review low stock" href="#analytics">${icon('chevron')}</a></div><div class="attention-item"><span class="attention-icon red">${icon('clock')}</span><div><strong>${state.invoices.filter(i=>i.status==='Overdue').length} overdue invoices</strong><p>${money(state.invoices.filter(i=>i.status==='Overdue').reduce((s,i)=>s+i.amount-i.paid,0))} outstanding</p></div><a class="icon-button" aria-label="Review invoices" href="#invoices">${icon('chevron')}</a></div><div class="attention-item"><span class="attention-icon blue">${icon('ship')}</span><div><strong>A container arrives soon</strong><p>MSCU 748291-6 · 12 October</p></div><a class="icon-button" aria-label="Review containers" href="#containers">${icon('chevron')}</a></div></div><div class="panel-foot"><span>A good day starts with a clear overview.</span>${icon('check')}</div></section></div><div class="dashboard-row"><section class="panel"><div class="panel-head"><div><h2>Recent sales orders</h2><p>From the first order to the final delivery.</p></div>${link('View all','sales')}</div>${table(['Order / client','Amount excl. tax','Status'],state.orders.slice(0,4).map(o=>[`<button class="product-name" data-action="record:orders:${o.id}"><strong>${o.id}</strong><small class="muted" style="display:block;margin-top:6px">${esc(o.party)}</small></button>`,money(o.amount),badge(o.status)]))}<div class="panel-foot"><span>${state.orders.filter(o=>o.status==='Ready to dispatch').length} orders ready for their next chapter.</span>${link('Open orders','sales')}</div></section><section class="panel"><div class="panel-head"><h2>On the water</h2>${link('View all','containers')}</div>${state.containers.slice(0,2).map(containerMini).join('')}</section></div><section class="panel"><div class="panel-head"><div><h2>Keep an eye on these</h2><p>Products below their reorder level.</p></div>${link('Stock health','analytics')}</div>${table(['Product','Available','Reorder level','Stock status',''],state.products.filter(p=>health(p)!=='Healthy').map(p=>[prodCell(p),num(available(p))+' units',num(p.reorder)+' units',badge(health(p)),btn('Reorder','reorder:'+p.id,'plus','small')]))}</section>`}
function products(){const list=state.products.filter(p=>match(p)&&(category==='All categories'||p.category===category)&&(tab==='All products'||health(p)===tab));return header('Products','One organised home for every product, pack and variant.',btn('Print catalogue','catalogue','book')+btn('Add product','add:product','plus','primary'))+`<div class="summary-strip"><div><small>Total products</small><strong>${state.products.length}</strong></div><div><small>Units on hand</small><strong>${num(state.products.reduce((s,p)=>s+p.stock,0))}</strong></div><div><small>Reserved for orders</small><strong>${num(state.products.reduce((s,p)=>s+p.reserved,0))}</strong></div><div><small>Categories</small><strong>${new Set(state.products.map(p=>p.category)).size}</strong></div></div><section class="panel">${tabs(['All products','Healthy','Low stock','Out of stock'])}${toolbar('Search name, SKU or alternate code…',`<select id="category" aria-label="Filter category">${['All categories',...new Set(state.products.map(p=>p.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`)}${table(['Product','Category','On hand','Reserved','Available','Trade price','Status'],list.map(p=>[prodCell(p),esc(p.category),num(p.stock),num(p.reserved),`<strong>${num(available(p))}</strong>`,money(p.price),badge(health(p))]))}${bottom(list.length)}</section>`}
function sales(){return listPage('Sales orders','Every order, from reserved stock to delivery.','orders',['All','Ready to dispatch','Backorder','Dispatched'],'New sales order','order')}
function purchasing(){return listPage('Purchase orders','Plan your next delivery and stay ahead of demand.','purchases',['All','Confirmed','In transit','Partially received','Received'],'New purchase order','purchase')}
function receiving(){return listPage('Goods received','Check what arrived, capture discrepancies, and put stock in its place.','grvs',['All','Received'],'Receive stock','grv')}
function invoices(){const unpaid=state.invoices.reduce((s,i)=>s+i.amount-i.paid,0);return header('Invoices & payments','Stay on top of what’s owed and what’s been paid.',btn('New invoice','add:invoice','plus','primary'))+`<div class="metric-grid">${metric('Total invoiced',money(state.invoices.reduce((s,i)=>s+i.amount,0)),'All demo invoices','receipt')}${metric('Outstanding',money(unpaid),'Unpaid and partially paid','clock')}${metric('Payments received',money(state.invoices.reduce((s,i)=>s+i.paid,0)),'Recorded in this demo','wallet')}${metric('Overdue',money(state.invoices.filter(i=>i.status==='Overdue').reduce((s,i)=>s+i.amount-i.paid,0)),'Requires follow-up','alert')}</div>`+recordsPanel('invoices',['All','Unpaid','Partially paid','Paid','Overdue'])}
function listPage(title,sub,key,ts,label,type){return header(title,sub,btn(label,'add:'+type,'plus','primary'))+recordsPanel(key,ts)}
function recordsPanel(key,ts){const list=state[key].filter(o=>match(o)&&(tab==='All'||o.status===tab));return `<section class="panel">${tabs(ts)}${toolbar()}${table([key==='grvs'?'GRV reference':'Reference',key==='purchases'||key==='grvs'?'Supplier':'Client','Date',key==='grvs'?'Accepted units':'Amount'+(key==='invoices'?' incl. demo tax':' excl. tax'),'Status',''],list.map(o=>[`<button class="text-link" data-action="record:${key}:${o.id}"><strong>${o.id}</strong></button>`,esc(o.party),o.date,key==='grvs'?num(o.qty):money(o.amount),badge(o.status),btn('View','record:'+key+':'+o.id,'chevron','small')]))}${bottom(list.length)}</section>`}
function relationships(key){let isClient=key==='clients',list=state[key].filter(match);return header(isClient?'Clients':'Suppliers',isClient?'Build lasting relationships. Keep every account in view.':'Your supply network, organised in one place.',btn('Add '+(isClient?'client':'supplier'),'add:'+(isClient?'client':'supplier'),'plus','primary'))+`<div class="summary-strip"><div><small>${isClient?'Client accounts':'Supplier accounts'}</small><strong>${state[key].length}</strong></div><div><small>${isClient?'Receivables snapshot':'Payables snapshot'}</small><strong>${money(state[key].reduce((s,p)=>s+p.balance,0))}</strong></div><div><small>Payment terms</small><strong>COD – 30 days</strong></div></div><section class="panel">${toolbar('Search company, contact or city…')}${table(['Company / contact','Email','Location','Terms','Opening balance','Status'],list.map(p=>[`<button class="product-name" data-action="party:${key}:${p.id}"><strong>${esc(p.name)}</strong><small class="muted" style="display:block;margin-top:6px">${esc(p.contact)}</small></button>`,esc(p.email),esc(p.city),esc(p.terms),money(p.balance),badge(p.status)]))}${bottom(list.length)}</section>`}
function containers(){return header('Containers','From origin port to your warehouse. Nothing lost along the way.',btn('Add container','add:container','plus','primary'))+`<div class="summary-strip"><div><small>Active containers</small><strong>${state.containers.length}</strong></div><div><small>Incoming cartons</small><strong>${num(state.containers.reduce((s,c)=>s+c.cartons,0))}</strong></div><div><small>Goods value</small><strong>${money(state.containers.reduce((s,c)=>s+c.value,0))}</strong></div></div><div class="grid-3">${state.containers.map(c=>`<section class="panel"><div class="panel-head"><div><span class="eyebrow">40 FT · SEA FREIGHT</span><h2>${esc(c.party)}</h2></div>${icon('ship')}</div>${containerMini(c)}<div class="panel-foot"><span>Goods ${money(c.value)}</span>${btn('Track & cost','container:'+c.id,'arrow','small')}</div></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Landed cost overview</h2><p>A complete view of what it costs to get your stock here.</p></div></div>${table(['Container','Goods','Freight','Duty','Clearing','Total landed'],state.containers.map(c=>[esc(c.id),money(c.value),money(c.freight),money(c.duty),money(c.clearing),`<strong>${money(c.value+c.freight+c.duty+c.clearing)}</strong>`]))}<p class="report-caption">Illustrative costs entered manually. These are not customs calculations or live shipment updates.</p></section>`}
function warehouse(){return header('Warehouse','Cape Town HQ · A place for everything, and everything in its place.',btn('Stock adjustment','add:adjustment','plus','primary'))+`<div class="summary-strip"><div><small>Active locations</small><strong>01</strong></div><div><small>Storage bins</small><strong>18</strong></div><div><small>Occupied bins</small><strong>${new Set(state.products.filter(p=>p.stock>0).map(p=>p.bin)).size}</strong></div><div><small>Inventory units</small><strong>${num(state.products.reduce((s,p)=>s+p.stock,0))}</strong></div></div><div class="dashboard-row"><section class="panel"><div class="panel-head"><div><h2>Warehouse layout</h2><p>Select a bin to see its stock.</p></div><span class="badge green">Cape Town HQ</span></div><div class="panel-body">${['A','B','C'].map(letter=>`<span class="eyebrow" style="margin:18px 0 12px">AISLE ${letter}</span><div class="bin-grid">${Array.from({length:6},(_,i)=>{let bin=letter+'-0'+(i+1),qty=state.products.filter(p=>p.bin===bin).reduce((s,p)=>s+p.stock,0);return `<button class="bin ${qty>1000?'full':!qty?'empty-bin':''}" data-action="bin:${bin}"><strong>${bin}</strong><small>${qty?num(qty)+' units':'Empty'}</small></button>`}).join('')}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Stock movement</h2></div><div class="panel-body">${state.activity.slice(0,6).map(a=>`<div class="activity">${icon('box')}<div>${esc(a.text)}<small>${esc(a.note)}</small></div><span>${a.time}</span></div>`).join('')}</div></section></div>`}
function analytics(){const list=state.products.filter(p=>health(p)!=='Healthy');return header('Stock health','Know what to replenish, what to move and what to rethink.',btn('Export stock report','export','down'))+`<div class="metric-grid">${metric('Healthy products',state.products.filter(p=>health(p)==='Healthy').length,'Above the reorder threshold','check')}${metric('Low stock',state.products.filter(p=>health(p)==='Low stock').length,'Below the reorder threshold','alert')}${metric('Out of stock',state.products.filter(p=>health(p)==='Out of stock').length,'Zero units available','box')}${metric('Expiry tracked',state.products.filter(p=>p.expiry).length,'Products with an expiry date','calendar')}</div><section class="panel"><div class="panel-head"><div><h2>Replenishment recommendations</h2><p>Suggested quantities bring available stock to twice the reorder level.</p></div></div>${table(['Product','Available','Target stock','Suggested order','Estimated cost',''],list.map(p=>{let qty=Math.max(0,p.reorder*2-available(p));return [prodCell(p),num(available(p)),num(p.reorder*2),num(qty)+' units',money(qty*p.cost),btn('Create PO','reorder:'+p.id,'plus','small')]}))}</section><div class="grid-2 section-gap"><section class="panel"><div class="panel-head"><div><h2>Category mix</h2><p>Current stock value at landed cost.</p></div></div><div class="panel-body">${[...new Set(state.products.map(p=>p.category))].map(c=>{let total=state.products.reduce((s,p)=>s+p.stock*p.cost,0),v=state.products.filter(p=>p.category===c).reduce((s,p)=>s+p.stock*p.cost,0);return `<div class="ledger-row"><span>${esc(c)}</span><strong>${money(v)}</strong></div><div class="progress" style="margin:9px 0"><span style="width:${total?v/total*100:0}%"></span></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Expiry watch</h2><p>Make room before time runs out.</p></div></div><div class="panel-body">${state.products.filter(p=>p.expiry).map(p=>`<div class="attention-item">${prodCell(p)}<span style="margin-left:auto">${esc(p.expiry)}</span></div>`).join('')||'<p>No expiry dates tracked.</p>'}<div class="notice section-gap">Forecasting concept: combine sales velocity, supplier lead time and seasonal demand. The prototype uses reorder thresholds; it does not predict demand.</div></div></section></div>`}
const accounts=[['1100','Bank','Asset',186420],['1200','Inventory','Asset',146845],['1300','Accounts receivable','Asset',39190],['1500','Equipment','Asset',45000],['2100','Accounts payable','Liability',205100],['2200','Tax payable','Liability',12355],['3000','Owner equity','Equity',150000],['4000','Sales revenue','Income',284650],['5000','Cost of sales','Expense',167940],['6100','Rent expense','Expense',18500],['6200','Operating expenses','Expense',48210]];
function accounting(){let content='';if(accountTab==='Overview')content=`<div class="metric-grid section-gap">${metric('Cash at bank','R 186,420','Illustrative opening snapshot','bank')}${metric('Accounts receivable','R 39,190','Illustrative opening snapshot','wallet')}${metric('Accounts payable','R 205,100','Illustrative opening snapshot','receipt')}${metric('Net profit · October','R 50,000','Illustrative reporting snapshot','chart')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Income & expenses</h2><p>October 2026 · Illustrative report</p></div></div><div class="panel-body">${[['Sales revenue',284650],['Cost of sales',-167940],['Gross profit',116710],['Rent',-18500],['Other operating expenses',-48210],['Net profit',50000]].map(([l,v],i)=>`<div class="ledger-row ${i===5?'total':''}"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Close the books with confidence</h2></div><div class="panel-body">${[['Bank reconciliation','Match incoming and outgoing payments.','Banking','bank'],['Journal entries','Review the debit and credit behind every entry.','Journals','book'],['Financial reports','Profit & loss, balance sheet and trial balance.','Reports','chart']].map(([t,s,to,i])=>`<div class="attention-item"><span class="attention-icon blue">${icon(i)}</span><div><strong>${t}</strong><p>${s}</p></div><button class="icon-button" data-action="account-tab:${to}" aria-label="Open ${to}">${icon('chevron')}</button></div>`).join('')}</div></section></div>`;
if(accountTab==='Banking')content=`<div class="grid-3 section-gap"><section class="panel account-card">${icon('bank')}<h3>Business current account</h3><div class="big-number">R 186,420</div><span class="muted">Illustrative balance · Manual bank feed</span></section><section class="panel account-card">${icon('wallet')}<h3>Yoco clearing</h3><div class="big-number">Not connected</div><span class="muted">Payment integration planned</span></section><section class="panel account-card">${icon('check')}<h3>Reconciliation</h3><div class="big-number">${state.transactions.filter(t=>t.status==='Unmatched').length} to match</div><span class="muted">Review before marking as reconciled</span></section></div><section class="panel section-gap"><div class="panel-head"><h2>Bank transactions</h2></div>${table(['Date','Description','Amount','Status',''],state.transactions.map(t=>[t.date,esc(t.memo),money(t.amount),badge(t.status),t.status==='Unmatched'?btn('Match','reconcile:'+t.id,'check','small'):'—']))}</section>`;
if(accountTab==='Supplier bills')content=`<section class="panel section-gap"><div class="panel-head"><div><h2>Supplier bills</h2><p>Track supplier invoices and record outgoing payments.</p></div>${btn('Add supplier bill','add:bill','plus','primary')}</div>${table(['Bill','Supplier','Date','Total','Balance due','Status',''],state.bills.map(b=>[b.id,esc(b.party),b.date,money(b.amount),money(b.amount-b.paid),badge(b.status),btn('View','record:bills:'+b.id,'chevron','small')]))}</section>`;
if(accountTab==='General ledger')content=`<section class="panel section-gap"><div class="panel-head"><div><h2>General ledger</h2><p>Demo journal activity · Each entry balances debit and credit.</p></div></div>${table(['Date','Reference','Account','Description','Debit','Credit'],state.journals.flatMap(j=>[[j.date,j.id,esc(j.debit),esc(j.memo),money(j.amount),'—'],[j.date,j.id,esc(j.credit),esc(j.memo),'—',money(j.amount)]]))}<p class="report-caption">This view reflects locally created journal entries. Operational transactions are not automatically posted in this prototype.</p></section>`;
if(accountTab==='Chart of accounts')content=`<section class="panel section-gap"><div class="panel-head"><h2>Chart of accounts</h2><span class="muted">Illustrative account balances</span></div>${table(['Code','Account name','Type','Balance'],accounts.map(a=>[a[0],a[1],badge(a[2]),money(a[3])]))}</section>`;
if(accountTab==='Journals')content=`<section class="panel section-gap"><div class="panel-head"><h2>General journal</h2>${btn('New journal','add:journal','plus','primary')}</div>${table(['Reference','Date','Description','Debit account','Credit account','Amount'],state.journals.map(j=>[j.id,j.date,esc(j.memo),esc(j.debit),esc(j.credit),money(j.amount)]))}</section>`;
if(accountTab==='Reports')content=`<div class="grid-3 section-gap">${[['Profit & loss','Revenue, cost of sales and operating expenses.'],['Balance sheet','Assets, liabilities and owner’s equity.'],['Trial balance','A balanced view of debit and credit balances.'],['Cash flow','Operating, investing and financing movements.'],['Aged receivables','See which client balances need attention.'],['Aged payables','Plan upcoming supplier payments.'],['Tax summary','Illustrative input and output tax overview.']].map(([n,d])=>`<button class="report-option" data-action="report:${n}">${icon('chart')}<h3>${n}</h3><p>${d}</p><span class="text-link">View report ${icon('arrow')}</span></button>`).join('')}</div>`;
return header('Accounting','A complete financial workspace, connected to your operations.',btn('New journal','add:journal','plus','primary'))+`<div class="notice">Accounting concept · Reports use an illustrative snapshot. Local journal and payment interactions demonstrate the workflow; no live ledger, bank connection or tax filing is active.</div><section class="panel">${tabs(['Overview','Banking','Supplier bills','Chart of accounts','Journals','General ledger','Reports'],accountTab,'account-tab')}</section>`+content}
function pricing(){return header('Price lists & catalogues','The right price for every relationship.',btn('Print catalogue','catalogue','print'))+`<div class="grid-3">${state.priceLists.map((l,i)=>`<section class="panel account-card">${icon('tag')}<h2>${esc(l.name)}</h2><div class="big-number">${l.discount?l.discount+'% off':'Base price'}</div><p class="muted">${state.products.length} products · ZAR · Excluding tax</p><div class="section-gap">${btn('View prices','prices:'+i,'arrow')}</div></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Packaging & pricing</h2><p>One base unit. Clear prices at every pack size.</p></div></div>${table(['Product','Individual','Inner pack','Carton','Carton price'],state.products.map(p=>[prodCell(p),money(p.price),p.inner+' units',p.carton+' inners / '+p.inner*p.carton+' units',money(p.price*p.inner*p.carton)]))}</section>`}
function settings(){return header('Settings','A single company today. Room to grow tomorrow.')+`<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Company details</h2></div><div class="panel-body"><form id="settings-form"><div class="form-grid"><label class="full">Company name<input name="name" required value="${esc(state.company.name)}"></label><label>Warehouse<input name="warehouse" required value="${esc(state.company.warehouse)}"></label><label>Currency<input value="ZAR · South African rand" readonly></label></div><div class="form-actions"><button class="btn primary">Save details</button></div></form></div></section><section class="panel"><div class="panel-head"><h2>Prototype information</h2></div><div class="panel-body"><div class="ledger-row"><span>Platform</span><strong>Static HTML, CSS & JavaScript</strong></div><div class="ledger-row"><span>Storage</span><strong>This browser only</strong></div><div class="ledger-row"><span>Warehousing</span><strong>Single location with bins</strong></div><div class="ledger-row"><span>Accounting & Yoco</span><strong>Visual concept</strong></div><div class="section-gap">${btn('Reset demo data','reset','refresh','danger')}</div><p class="form-help">Reset removes local edits and restores the sample company. No real customer, supplier or financial data should be entered into this prototype.</p></div></section></div>`}
function render(){let fn={overview,products,sales,purchasing,receiving,containers,warehouse,analytics,invoices,accounting,pricing,settings,clients:()=>relationships('clients'),suppliers:()=>relationships('suppliers')};$('main').innerHTML=(fn[route]||overview)();$('crumb').textContent=(allRoutes.find(r=>r[0]===route)||[])[1]||'Overview';document.title='Stocky · '+$('crumb').textContent;document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===route));document.querySelector('.workspace strong').textContent=state.company.name;const count=document.querySelector('[data-route="sales"] .count');if(count)count.textContent=state.orders.filter(o=>o.status!=='Dispatched').length;document.querySelector('.location').innerHTML=icon('warehouse')+esc(state.company.warehouse);hydrate()}
function navigate(){route=location.hash.slice(1)||'overview';if(!allRoutes.some(r=>r[0]===route))route='overview';tab=route==='products'?'All products':'All';query='';category='All categories';document.body.classList.remove('nav-open');render();window.scrollTo(0,0)}
function openDialog(title,body){$('dialog-title').textContent=title;$('dialog-content').innerHTML=body;if(!$('dialog').open)$('dialog').showModal();hydrate()}
const close=()=>$('dialog').close();
function showProduct(id){const p=product(id);openDialog(p.name,`<div class="detail-hero"><span class="product-art ${p.tone}">${icon(p.art)}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.id)} · ${esc(p.category)} / ${esc(p.sub)}</p></div></div><div class="details-grid">${[['Primary SKU',p.id],['Variant',p.color],...p.codes.map((c,i)=>['Alternate code '+(i+1),c]),['Weight',p.weight+' kg'],['Bin',p.bin],['Expiry',p.expiry||'Not applicable']].map(([k,v])=>`<div class="detail-item"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3 class="form-section">Packaging hierarchy</h3><div class="pack-flow"><div><small>Individual</small><strong>1</strong><small>${money(p.price)}</small></div><div><small>Inner pack</small><strong>${p.inner} units</strong><small>${money(p.price*p.inner)}</small></div><div><small>Carton</small><strong>${p.carton} inners</strong><small>${p.carton*p.inner} units · ${money(p.price*p.inner*p.carton)}</small></div></div><div class="summary-strip"><div><small>On hand</small><strong>${p.stock}</strong></div><div><small>Reserved</small><strong>${p.reserved}</strong></div><div><small>Available</small><strong>${available(p)}</strong></div></div><div class="ledger-row"><span>Landed unit cost</span><strong>${money(p.cost)}</strong></div><div class="ledger-row"><span>Reorder level</span><strong>${p.reorder} units</strong></div><h3 class="form-section">Product images · up to 5</h3><div class="photo-slots">${Array.from({length:5},(_,i)=>p.images?.[i]?`<img src="${esc(p.images[i])}" alt="Product image ${i+1}">`:`<div>${i+1}</div>`).join('')}</div><p class="form-help">Image slots are ready for your client’s product photography.</p><div class="form-actions">${btn('Edit product','edit:'+p.id,'pen')}${btn('Create purchase order','reorder:'+p.id,'plus','primary')}</div>`)}
const field=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,values,selected='')=>`<label>${label}<select name="${name}">${values.map(v=>{let [value,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
const productOptions=()=>state.products.map(p=>[p.id,p.id+' · '+p.name]);
const partyOptions=k=>state[k].map(p=>p.name);
const formWrap=(type,body,label='Save',id='')=>`<form id="entry-form" data-type="${type}" data-id="${esc(id)}">${body}<div class="error" id="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">${icon('check')}${label}</button></div></form>`;
function openForm(type,preset=''){
 let body='',title='',label='Save',id='';
 if(type==='product'){
 const p=product(preset)||{name:'',id:'',codes:['','',''],category:'Kitchen & Home',sub:'',color:'',weight:0,inner:6,carton:4,cost:0,price:0,reorder:50,bin:'A-01',expiry:''};id=p.id;title=id?'Edit product':'Add a product';label=id?'Save product':'Create product';
 body=`<h3 class="form-section">Product information</h3><div class="form-grid">${field('Product name','name',p.name,'text','required maxlength="100"')}${field('Primary SKU','sku',p.id,'text','required maxlength="40"')}${field('Category','category',p.category,'text','required')}${field('Subcategory','sub',p.sub)}${field('Colour / variant','color',p.color)}${field('Weight per unit (kg)','weight',p.weight,'number','min="0" step="0.01"')}${p.codes.map((c,i)=>field('Alternate code '+(i+1),'code'+i,c)).join('')}${field('Expiry date (optional)','expiry',p.expiry,'date')}</div><h3 class="form-section">Packaging & pricing</h3><div class="form-grid">${field('Units per inner pack','inner',p.inner,'number','required min="1" step="1"')}${field('Inner packs per carton','carton',p.carton,'number','required min="1" step="1"')}${field('Landed cost per unit (R)','cost',p.cost,'number','required min="0" step="0.01"')}${field('Selling price per unit (R)','price',p.price,'number','required min="0" step="0.01"')}${field('Reorder level (units)','reorder',p.reorder,'number','required min="0" step="1"')}${select('Storage bin','bin',bins(),p.bin)}<label class="full">Product photos (maximum 5, 500 KB each)<input type="file" name="photos" accept="image/png,image/jpeg,image/webp" multiple></label></div><p class="form-help">New products start with zero stock. Receive a delivery or record a stock adjustment to add units. ${id?'Leaving photos empty preserves existing images.':''}</p>`;
 } else if(type==='client'||type==='supplier'){
 const p=state[type==='client'?'clients':'suppliers'].find(p=>p.id===preset)||{};id=p.id||'';title=(id?'Edit ':'Add ')+type;
 body=`<div class="form-grid">${field('Company name','name',p.name||'','text','required')}${field('Contact person','contact',p.contact||'','text','required')}${field('Email','email',p.email||'','email','required')}${field('Phone','phone',p.phone||'','tel')}${field('City / country','city',p.city||'','text','required')}${select('Payment terms','terms',['COD','14 days','30 days'],p.terms||'30 days')}${field('Opening balance (R)','balance',p.balance||0,'number','required min="0" step="0.01"')}</div><p class="form-help">This account balance is a visual opening snapshot, separate from the sample invoices.</p>`;
 } else if(['order','purchase','invoice','bill'].includes(type)){
 title={order:'New sales order',purchase:'New purchase order',invoice:'New invoice',bill:'New supplier bill'}[type];label={order:'Create order',purchase:'Create purchase order',invoice:'Create invoice',bill:'Create bill'}[type];const p=product(preset)||state.products[0];
 body=`<div class="notice">${type==='order'?'Available units are reserved when you create the order. Orders exceeding availability go to backorder.':type==='purchase'?'Create the order now. Receive the actual delivery separately using a GRV.':'Invoices track payment only. Stock leaves the warehouse when a sales order is dispatched.'}</div><div class="form-grid">${select(['purchase','bill'].includes(type)?'Supplier':'Client','party',partyOptions(['purchase','bill'].includes(type)?'suppliers':'clients'))}${field(type==='purchase'?'Expected date':'Issue date','date','2026-10-07','date','required')}${select('Product','product',productOptions(),p.id)}${select('Packaging','pack',['Individual','Inner','Carton'])}${field('Quantity of selected packs','qty',preset?Math.max(1,p.reorder*2-available(p)):1,'number','required min="1" step="1"')}${field('Unit price / cost (R)','rate',['purchase','bill'].includes(type)?p.cost:p.price,'number','required min="0.01" step="0.01"')}${['invoice','bill'].includes(type)?field('Illustrative tax rate (%)','tax',15,'number','required min="0" max="100" step="0.01"'):''}</div><div id="pack-preview" class="notice section-gap"></div><p class="form-help">Prototype entry supports one product line per document. Prices shown are per individual unit.</p>`;
 } else if(type==='grv'){
 title='Receive stock';label='Confirm receipt';const po=state.purchases.find(p=>p.id===preset)||state.purchases.find(p=>p.received<p.qty);if(!po){openDialog(title,'<div class="empty"><h3>No open purchase orders</h3>Create a purchase order before receiving stock.</div>');return}
 body=`<div class="notice">Count the delivery first. Only accepted units are added to stock; rejected units remain outstanding on the purchase order.</div><div class="form-grid">${select('Purchase order','po',state.purchases.filter(p=>p.received<p.qty).map(p=>[p.id,p.id+' · '+p.party]),po.id)}${field('Received date','date','2026-10-07','date','required')}${field('Accepted units','qty',po.qty-po.received,'number','required min="1" step="1"')}${field('Rejected / damaged units','rejected',0,'number','required min="0" step="1"')}${select('Destination bin','bin',bins(),product(po.product).bin)}${field('Supplier delivery reference','reference','','text','required')}<label class="full">Discrepancy notes<textarea name="notes" placeholder="Short delivery, damage or other observations…"></textarea></label></div><div class="notice section-gap" id="grv-preview"></div>`;
 } else if(type==='container'){
 title='Add container';body=`<div class="form-grid">${field('Container number','id','','text','required')}${select('Supplier','party',partyOptions('suppliers'))}${field('Origin port','origin','Shenzhen','text','required')}${field('Destination port','destination','Cape Town','text','required')}${field('Estimated arrival','eta','2026-10-20','date','required')}${field('Cartons','cartons',100,'number','required min="1" step="1"')}${field('Goods value (R)','value',0,'number','required min="0" step="0.01"')}${field('Freight (R)','freight',0,'number','required min="0" step="0.01"')}${field('Duty (R)','duty',0,'number','required min="0" step="0.01"')}${field('Clearing (R)','clearing',0,'number','required min="0" step="0.01"')}</div>`;
 } else if(type==='adjustment'){
 title='Stock adjustment';label='Apply adjustment';body=`<div class="notice amber">Enter the physical count in individual units. Reserved units cannot exceed the new count. Each adjustment is recorded in stock movement.</div><div class="form-grid">${select('Product','product',productOptions())}${field('Counted on hand (units)','qty',0,'number','required min="0" step="1"')}<label class="full">Reason<textarea name="reason" required placeholder="Explain the stocktake variance…"></textarea></label></div>`;
 } else if(type==='journal'){
 title='New journal entry';label='Post demo journal';body=`<div class="notice">A balanced two-line journal: the same amount is debited to one account and credited to another. Reports remain the illustrative opening snapshot.</div><div class="form-grid">${field('Date','date','2026-10-07','date','required')}${field('Description','memo','','text','required')}${select('Debit account','debit',accounts.map(a=>a[0]+' · '+a[1]))}${select('Credit account','credit',accounts.map(a=>a[0]+' · '+a[1]),'3000 · Owner equity')}${field('Amount (R)','amount',0,'number','required min="0.01" step="0.01"')}</div>`;
 }
 openDialog(title,formWrap(type,body,label,id));updateFormPreview();
}
function bins(){return ['A','B','C'].flatMap(a=>Array.from({length:6},(_,i)=>a+'-0'+(i+1)))}
function updateFormPreview(){const f=$('entry-form');if(!f)return;const d=Object.fromEntries(new FormData(f));if($('pack-preview')){let p=product(d.product),units=Number(d.qty)*(d.pack==='Carton'?p.inner*p.carton:d.pack==='Inner'?p.inner:1),value=units*Number(d.rate);$('pack-preview').textContent=`${num(units)} individual units · ${money(value)} excluding tax${d.tax?' · '+money(value*(1+Number(d.tax)/100))+' including demo tax':''} · ${num(available(p))} available`}
 if($('grv-preview')){let po=state.purchases.find(p=>p.id===d.po);$('grv-preview').textContent=`${product(po.product).name} · ${po.qty-po.received} units outstanding · ${po.party}`}}
async function submitEntry(f){const d=Object.fromEntries(new FormData(f)),type=f.dataset.type,id=f.dataset.id;let n=k=>Number(d[k]);try{
 if(type==='product'){
 if(state.products.some(p=>p.id===d.sku&&p.id!==id))throw Error('This primary SKU already exists. Choose a unique code.');
 const old=product(id);if(old&&d.sku!==id)throw Error('Keep the existing primary SKU so linked stock records remain intact. Alternate codes can be changed.');
 const files=[...f.elements.photos.files];if(files.length>5||files.some(p=>p.size>500000))throw Error('Use up to 5 images, each smaller than 500 KB.');if(files.some(p=>!['image/png','image/jpeg','image/webp'].includes(p.type)))throw Error('Please choose PNG, JPEG or WebP images.');
 const images=files.length?await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read image.'));r.readAsDataURL(file)}))):old?.images||[];
 const p={...old,id:d.sku,name:d.name,category:d.category,sub:d.sub,color:d.color,codes:[d.code0,d.code1,d.code2],weight:n('weight'),inner:n('inner'),carton:n('carton'),cost:n('cost'),price:n('price'),reorder:n('reorder'),bin:d.bin,expiry:d.expiry,images,stock:old?.stock||0,reserved:old?.reserved||0,art:old?.art||'box',tone:old?.tone||''};if(old)Object.assign(old,p);else state.products.unshift(p);
 } else if(type==='client'||type==='supplier'){
 const key=type==='client'?'clients':'suppliers';const old=state[key].find(p=>p.id===id);let obj={...d,balance:n('balance'),id:id||(type==='client'?'CL-':'SP-')+String(state[key].length+1).padStart(3,'0'),status:old?.status||'Active'};if(old)Object.assign(old,obj);else state[key].unshift(obj);
 } else if(['order','purchase','invoice','bill'].includes(type)){
 const p=product(d.product),qty=n('qty')*(d.pack==='Carton'?p.inner*p.carton:d.pack==='Inner'?p.inner:1),amount=Math.round(qty*n('rate')*100)/100;
 if(!Number.isSafeInteger(qty)||qty<1)throw Error('Enter a whole, positive pack quantity.');
 const row={party:d.party,product:p.id,qty,amount,date:d.date};
 if(type==='order'){row.id='SO-'+(2049+state.orders.length-4);row.status=available(p)>=qty?'Ready to dispatch':'Backorder';if(row.status==='Ready to dispatch')p.reserved+=qty;state.orders.unshift(row)}
 if(type==='purchase'){row.id='PO-'+(1087+state.purchases.length-3);row.status='Confirmed';row.received=0;state.purchases.unshift(row)}
 if(type==='bill'){row.id='BILL-'+String(802+state.bills.length-2).padStart(4,'0');row.status='Unpaid';row.paid=0;row.tax=n('tax');row.amount=Math.round(amount*(1+row.tax/100)*100)/100;state.bills.unshift(row)}
 if(type==='invoice'){row.id='INV-'+(3093+state.invoices.length-3);row.status='Unpaid';row.paid=0;row.tax=n('tax');row.amount=Math.round(amount*(1+row.tax/100)*100)/100;state.invoices.unshift(row)}
 log(row.id+' created',row.party+' · '+qty+' units');
 } else if(type==='grv'){
 let po=state.purchases.find(p=>p.id===d.po),p=product(po.product);if(n('qty')+n('rejected')>po.qty-po.received)throw Error('Accepted plus rejected units cannot exceed the outstanding order quantity.');if(!Number.isInteger(n('qty'))||!Number.isInteger(n('rejected')))throw Error('Enter whole unit quantities.');
 p.stock+=n('qty');p.bin=d.bin;po.received+=n('qty');po.status=po.received===po.qty?'Received':'Partially received';const row={...d,id:'GRV-'+String(422+state.grvs.length-1).padStart(4,'0'),party:po.party,product:p.id,qty:n('qty'),rejected:n('rejected'),status:'Received'};state.grvs.unshift(row);log(row.id+' received into '+d.bin,n('qty')+' units · '+p.name);
 } else if(type==='container'){
 if(state.containers.some(c=>c.id===d.id))throw Error('This container number already exists.');state.containers.push({...d,cartons:n('cartons'),value:n('value'),freight:n('freight'),duty:n('duty'),clearing:n('clearing'),status:'In transit',progress:0});
 } else if(type==='adjustment'){
 const p=product(d.product);if(n('qty')<p.reserved)throw Error('Count cannot be below '+p.reserved+' reserved units. Resolve the reservations first.');let difference=n('qty')-p.stock;p.stock=n('qty');log('Stock adjusted · '+p.id,(difference>=0?'+':'')+difference+' units · '+d.reason);
 } else if(type==='journal'){
 if(d.debit===d.credit)throw Error('Choose different debit and credit accounts.');state.journals.unshift({...d,id:'JRN-'+String(105+state.journals.length-2).padStart(4,'0'),amount:n('amount'),status:'Posted'});
 }
 persist();close();render();toast('Saved to your browser demo.');
 }catch(error){$('form-error').textContent=error.message}
}
function record(key,id){const o=state[key].find(o=>o.id===id),p=product(o.product);let actions=btn('Print','print','print');
 if(key==='orders'&&o.status==='Ready to dispatch')actions+=btn('Dispatch order','dispatch:'+id,'truck','primary');
 if(key==='orders'&&o.status==='Backorder')actions+=btn('Allocate stock','allocate:'+id,'box','primary');
 if(key==='orders'&&o.status==='Dispatched')actions+=btn('View waybill','waybill:'+id,'truck');
 if(key==='purchases'&&o.received<o.qty)actions+=btn('Receive delivery','receive-po:'+id,'down','primary');
 if(['invoices','bills'].includes(key)&&o.paid<o.amount)actions+=btn('Record payment','payment:'+id+':'+key,'wallet','primary');
 openDialog(o.id,`<div class="doc-head"><div><span class="eyebrow">${['purchases','grvs','bills'].includes(key)?'SUPPLIER':'BILL TO'}</span><h3>${esc(o.party)}</h3><p class="form-help">${esc(state.company.name)} · ${esc(state.company.warehouse)}</p></div><div>${badge(o.status)}<p class="form-help">${o.date}</p></div></div>${table(['Product','Units',key==='grvs'?'Rejected':'Total'],[[esc(p.name),num(o.qty),key==='grvs'?num(o.rejected||0):money(o.amount)]])}${key==='purchases'?`<div class="ledger-row"><span>Received / ordered</span><strong>${o.received} / ${o.qty} units</strong></div>`:''}${key==='grvs'?`<div class="ledger-row"><span>Purchase order</span><strong>${esc(o.po)}</strong></div><div class="ledger-row"><span>Destination bin</span><strong>${esc(o.bin)}</strong></div><p class="form-help">${esc(o.notes||'No discrepancies recorded.')}</p>`:''}${['invoices','bills'].includes(key)?`<div class="doc-total"><div class="ledger-row"><span>Invoice total</span><strong>${money(o.amount)}</strong></div><div class="ledger-row"><span>Paid</span><strong>${money(o.paid)}</strong></div><div class="ledger-row total"><span>Balance due</span><strong>${money(o.amount-o.paid)}</strong></div></div><p class="form-help">Demo invoice · includes ${o.tax??15}% illustrative tax. Not a live tax document.</p>`:''}<div class="form-actions">${actions}</div>`)}
function party(key,id){const p=state[key].find(p=>p.id===id);openDialog(p.name,`<div class="details-grid">${[['Contact',p.contact],['Email',p.email],['Phone',p.phone],['Location',p.city],['Payment terms',p.terms],['Opening balance',money(p.balance)]].map(([l,v])=>`<div class="detail-item"><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3 class="form-section">Recent documents</h3>${table(['Reference','Status','Amount'],state[key==='clients'?'orders':'purchases'].filter(o=>o.party===p.name).map(o=>[o.id,badge(o.status),money(o.amount)]))}<div class="form-actions">${btn('Edit details','edit-party:'+key+':'+id,'pen')}</div>`)}
function showContainer(id){const c=state.containers.find(c=>c.id===id);openDialog(c.id,`${containerMini(c)}<div class="status-line"><span class="done">Booked</span><span class="done">On the water</span><span>Customs</span><span>Received</span></div><div class="details-grid"><div class="detail-item"><small>Supplier</small><strong>${esc(c.party)}</strong></div><div class="detail-item"><small>Estimated arrival</small><strong>${c.eta}</strong></div></div><h3 class="form-section">Landed cost breakdown</h3>${[['Goods value',c.value],['Freight',c.freight],['Import duty',c.duty],['Clearing & handling',c.clearing],['Total landed cost',c.value+c.freight+c.duty+c.clearing]].map(([k,v])=>`<div class="ledger-row"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<p class="form-help">Cost allocation preview · ${(c.value+c.freight+c.duty+c.clearing)/c.cartons>0?money((c.value+c.freight+c.duty+c.clearing)/c.cartons):money(0)} per carton using equal-carton allocation. Product-level allocation is a planned production workflow.</p><div class="form-actions">${btn('Print summary','print','print')}</div>`)}
function report(name){let rows=[];if(name==='Profit & loss')rows=[['Sales revenue',284650],['Cost of sales',-167940],['Gross profit',116710],['Rent expense',-18500],['Operating expenses',-48210],['Net profit',50000]];if(name==='Balance sheet')rows=[['ASSETS',''],['Bank',186420],['Inventory',146845],['Accounts receivable',39190],['Equipment',45000],['Total assets',417455],['LIABILITIES & EQUITY',''],['Accounts payable',205100],['Tax payable',12355],['Owner equity',150000],['Current earnings',50000],['Total liabilities & equity',417455]];if(name==='Cash flow')rows=[['Opening cash',120000],['Operating cash flow',86420],['Investing cash flow',-20000],['Financing cash flow',0],['Closing cash',186420]];if(name==='Tax summary')rows=[['Illustrative output tax',42697.5],['Illustrative input tax',30342.5],['Net tax payable',12355]];
 let content=rows.length?rows.map(([l,v])=>`<div class="ledger-row"><span>${l}</span><strong>${v===''?'':money(v)}</strong></div>`).join(''):name==='Trial balance'?table(['Account','Debit','Credit'],accounts.map(a=>[a[0]+' · '+a[1],['Asset','Expense'].includes(a[2])?money(a[3]):'—',['Liability','Equity','Income'].includes(a[2])?money(a[3]):'—']).concat([['Total',money(652105),money(652105)]])):table(['Account','Terms','Opening balance'],state[name==='Aged receivables'?'clients':'suppliers'].map(p=>[esc(p.name),p.terms,money(p.balance)]));
 if(name.startsWith('Aged'))content='<div class="notice">Account opening balances preview. Invoice-level ageing buckets will be connected to the production ledger.</div>'+content;
 openDialog(name,`<div class="doc-head"><div><h3>${esc(state.company.name)}</h3><p class="form-help">October 2026 · ZAR · Illustrative snapshot</p></div>${icon('chart')}</div>${content}<p class="form-help">Sample reporting layout. Demo edits do not post to these financial statements.</p><div class="form-actions">${btn('Print report','print','print')}</div>`)}
function exportCSV(){let key={products:'products',overview:'products',analytics:'products',warehouse:'products',sales:'orders',purchasing:'purchases',receiving:'grvs',containers:'containers',clients:'clients',suppliers:'suppliers',invoices:'invoices',accounting:'journals',pricing:'products'}[route]||'products';let data=state[key].filter(match);if(key==='products'){if(category!=='All categories')data=data.filter(p=>p.category===category);if(['Healthy','Low stock','Out of stock'].includes(tab))data=data.filter(p=>health(p)===tab)}else if(tab!=='All')data=data.filter(p=>p.status===tab);if(!data.length){toast('No records to export.');return}let columns=Object.keys(data[0]).filter(k=>k!=='images'),cell=v=>{v=Array.isArray(v)?v.join(' | '):String(v??'');if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'};let csv=[columns.map(cell).join(','),...data.map(row=>columns.map(c=>cell(row[c])).join(','))].join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let a=document.createElement('a');a.href=url;a.download='stocky-'+key+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV downloaded.');}
function searchDialog(){openDialog('Find anything',`<label class="search-field" style="max-width:none;border:1px solid var(--line);border-radius:7px;padding:5px 12px">${icon('search')}<input id="search-all" placeholder="Products, clients, suppliers, pages…" aria-label="Search all records"></label><div class="search-results" id="search-results"></div>`);searchAll('');$('search-all').focus()}
function searchAll(q){let list=[...allRoutes.map(([id,name])=>({name,kind:'Page',action:'go:'+id})),...state.products.map(p=>({name:p.name,kind:p.id,keywords:p.codes.join(' '),action:'product:'+p.id})),...['clients','suppliers'].flatMap(key=>state[key].map(p=>({name:p.name,kind:key,action:'party:'+key+':'+p.id})))].filter(r=>(r.name+' '+r.kind+' '+(r.keywords||'')).toLowerCase().includes(q.toLowerCase())).slice(0,10);$('search-results').innerHTML=list.length?list.map(r=>`<button class="search-result" data-action="${esc(r.action)}"><span>${esc(r.name)}</span><small>${esc(r.kind)}</small></button>`).join(''):'<div class="empty">No matching records.</div>'}
function catalogue(){openDialog('Trade catalogue',`<div class="doc-head"><div><h3>${esc(state.company.name)}</h3><p class="form-help">October 2026 · Standard trade · Prices exclude tax</p></div>${icon('book')}</div><div class="catalogue-grid">${state.products.map(p=>`<div class="catalogue-card"><span class="product-art ${p.tone}">${icon(p.art)}</span><h3>${esc(p.name)}</h3><p>${esc(p.id)} · ${esc(p.color)}</p><strong>${money(p.price)}</strong><p>Inner ${p.inner} · Carton ${p.inner*p.carton}</p></div>`).join('')}</div><div class="form-actions">${btn('Print / save PDF','print','print','primary')}</div>`)}
function handleAction(action){let [a,b,c]=action.split(':');
 if(a==='tab'){tab=b;render()}
 else if(a==='account-tab'){accountTab=b;render()}
 else if(a==='add')openForm(b);
 else if(a==='product')showProduct(b);
 else if(a==='edit')openForm('product',b);
 else if(a==='edit-party')openForm(b==='clients'?'client':'supplier',c);
 else if(a==='record')record(b,c);
 else if(a==='party')party(b,c);
 else if(a==='container')showContainer(b);
 else if(a==='reorder')openForm('purchase',b);
 else if(a==='receive-po')openForm('grv',b);
 else if(a==='close')close();
 else if(a==='print')window.print();
 else if(a==='export')exportCSV();
 else if(a==='catalogue')catalogue();
 else if(a==='report')report(b);
 else if(a==='go'){close();location.hash=b}
 else if(a==='quick')openDialog('What would you like to create?',`<div class="grid-2">${[['Sales order','order','receipt'],['Purchase order','purchase','bag'],['Goods received','grv','down'],['Invoice','invoice','wallet'],['Journal entry','journal','book'],['Product','product','box']].map(([n,t,i])=>`<button class="report-option" data-action="add:${t}">${icon(i)}<h3>${n}</h3></button>`).join('')}</div>`);
 else if(a==='date')openDialog('Reporting period','<div class="notice">The dashboard shows an illustrative snapshot for 1–7 October 2026. Live date filtering will be connected to transaction history in the working system.</div>');
 else if(a==='bin'){const ps=state.products.filter(p=>p.bin===b);openDialog('Bin '+b,`<p class="form-help">${esc(state.company.warehouse)}</p>${table(['Product','On hand','Reserved','Available'],ps.map(p=>[esc(p.name),p.stock,p.reserved,available(p)]))}`)}
 else if(a==='dispatch'){
 const o=state.orders.find(o=>o.id===b),p=product(o.product);openDialog('Confirm dispatch',`<div class="notice">Dispatch ${o.id} to ${esc(o.party)}. This deducts ${o.qty} units from on-hand stock and releases the same reservation.</div><div class="form-actions">${btn('Cancel','close')}${btn('Confirm dispatch','confirm-dispatch:'+b,'truck','primary')}</div>`);
 }
 else if(a==='confirm-dispatch'){
 const o=state.orders.find(o=>o.id===b),p=product(o.product);if(o.status!=='Ready to dispatch'||p.stock<o.qty||p.reserved<o.qty){toast('This order cannot be dispatched. Check available stock.');return}p.stock-=o.qty;p.reserved-=o.qty;o.status='Dispatched';log(o.id+' dispatched',o.qty+' units · '+o.party);close();render();toast('Order dispatched. Stock and reservation updated.');
 }
 else if(a==='allocate'){
 const o=state.orders.find(o=>o.id===b),p=product(o.product);if(o.status!=='Backorder')return;if(available(p)<o.qty){toast('Not enough available stock. Receive the delivery first.');return}p.reserved+=o.qty;o.status='Ready to dispatch';log(o.id+' allocated',o.qty+' units reserved');render();record('orders',b);toast('Stock reserved. Order is ready to dispatch.');
 }
 else if(a==='waybill'){const o=state.orders.find(o=>o.id===b);openDialog('Waybill · WB-'+b.slice(3),`<div class="doc-head"><div><span class="eyebrow">DELIVER TO</span><h3>${esc(o.party)}</h3><p class="form-help">Order ${o.id} · From ${esc(state.company.warehouse)}</p></div>${badge('Dispatched')}</div>${table(['Product','Units'],[[esc(product(o.product).name),o.qty]])}<div class="ledger-row"><span>Received by</span><span>________________</span></div><div class="ledger-row"><span>Signature / date</span><span>________________</span></div><p class="form-help">Demo dispatch document. Delivery address and courier booking are not connected.</p><div class="form-actions">${btn('Print waybill','print','print')}</div>`)}
 else if(a==='payment'){const key=c||'invoices';const i=state[key].find(i=>i.id===b);openDialog('Record payment',`<form id="payment-form" data-id="${b}" data-key="${key}"><div class="notice">${i.id} · ${esc(i.party)} · Balance ${money(i.amount-i.paid)}</div><div class="form-grid">${field('Payment amount (R)','amount',(i.amount-i.paid).toFixed(2),'number',`required min="0.01" max="${(i.amount-i.paid).toFixed(2)}" step="0.01"`)}${select('Payment method','method',['Bank transfer','Cash','Card · manual record'])}${field('Payment reference','reference','','text','required')}</div><p class="form-help">Records the payment locally. No money is charged or transferred.</p><div class="form-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">Record payment</button></div></form>`)}
 else if(a==='reconcile'){const t=state.transactions.find(t=>t.id===b);openDialog('Review bank transaction',`<div class="notice">${esc(t.memo)} · ${money(t.amount)}</div><form id="reconcile-form" data-id="${b}"><div class="form-grid">${select('Allocate to account','account',accounts.map(a=>a[0]+' · '+a[1]))}${field('Matching reference','reference','','text','required')}</div><p class="form-help">This demonstrates a manual allocation; it does not connect to a bank or post to the ledger.</p><div class="form-actions">${btn('Cancel','close')}<button class="btn primary">Confirm match</button></div></form>`)}
 else if(a==='prices'){const l=state.priceLists[Number(b)];openDialog(l.name,`${table(['Product','Standard','Your price'],state.products.map(p=>[esc(p.name),money(p.price),money(p.price*(1-l.discount/100))]))}<p class="form-help">Prices per individual unit, excluding tax.</p><div class="form-actions">${btn('Print price list','print','print')}</div>`)}
 else if(a==='reset')openDialog('Reset demo data?',`<p>Your local products, orders and other edits will be removed and replaced with the original sample data.</p><div class="form-actions">${btn('Keep my changes','close')}${btn('Reset demo','confirm-reset','refresh','danger')}</div>`);
 else if(a==='confirm-reset'){localStorage.removeItem('stocky-demo-v1');location.reload()}
}
$('navigation').innerHTML=routes.map(([label,items])=>`<div class="nav-label">${label}</div>${items.map(([id,n,i])=>`<a href="#${id}" data-route="${id}" class="nav-link">${icon(i)}${n}${id==='sales'?'<span class="count">3</span>':''}</a>`).join('')}`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();handleAction(b.dataset.action)}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){let start=e.target.selectionStart;query=e.target.value;render();$('table-search').focus();$('table-search').setSelectionRange(start,start)}if(e.target.id==='search-all')searchAll(e.target.value);if(e.target.closest('#entry-form'))updateFormPreview()});
document.addEventListener('change',e=>{if(e.target.id==='category'){category=e.target.value;render()}const f=$('entry-form');if(f&&e.target.name==='product'&&['order','purchase','invoice','bill'].includes(f.dataset.type)){f.elements.rate.value=['purchase','bill'].includes(f.dataset.type)?product(e.target.value).cost:product(e.target.value).price;updateFormPreview()}if(f&&e.target.name==='po'){let po=state.purchases.find(p=>p.id===e.target.value);f.elements.qty.value=po.qty-po.received;f.elements.bin.value=product(po.product).bin;updateFormPreview()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='entry-form'){const b=f.querySelector('[type="submit"]');b.disabled=true;await submitEntry(f);if(b.isConnected)b.disabled=false}if(f.id==='settings-form'){const d=Object.fromEntries(new FormData(f));state.company.name=d.name;state.company.warehouse=d.warehouse;persist();render();toast('Company details saved.')}
if(f.id==='payment-form'){let i=state[f.dataset.key||'invoices'].find(i=>i.id===f.dataset.id),d=Object.fromEntries(new FormData(f)),amount=Number(d.amount);if(amount<=0||amount>Math.round((i.amount-i.paid)*100)/100)return;i.paid=Math.round((i.paid+amount)*100)/100;i.status=i.paid>=i.amount?'Paid':'Partially paid';log(i.id+' payment recorded',money(amount)+' · '+d.method+' · '+d.reference);close();render();toast('Payment recorded. Invoice balance updated.')}
if(f.id==='reconcile-form'){let t=state.transactions.find(t=>t.id===f.dataset.id);t.status='Reconciled';t.account=f.elements.account.value;t.reference=f.elements.reference.value;persist();close();render();toast('Demo transaction matched.')}
});
$('close-dialog').onclick=close;$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
$('menu-toggle').onclick=()=>document.body.classList.toggle('nav-open');$('scrim').onclick=()=>document.body.classList.remove('nav-open');$('global-search').onclick=searchDialog;
$('notifications').onclick=()=>openDialog('Your activity',`<div>${state.activity.map(a=>`<div class="activity">${icon('check')}<div>${esc(a.text)}<small>${esc(a.note)}</small></div><span>${a.time}</span></div>`).join('')}</div>`);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog()}});
window.addEventListener('hashchange',navigate);navigate();
